import{_ as e,a as o,o as a,a4 as d}from"./chunks/framework.-FZumj2l.js";const u=JSON.parse('{"title":"Dashboard Statistics","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"rest-over-all","title":"Over-all","description":"Headline KPIs for the top \\"Overall Details\\" cards — customers, orders, sales, average order value and unpaid-invoice total, each compared against the previous period.","query":"curl -X GET \\"https://your-domain.com/api/admin/dashboard/stats?type=over-all&start=2026-05-03&end=2026-06-02&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"type\\": \\"over-all\\",\\n    \\"dateRange\\": \\"03 May - 02 Jun\\",\\n    \\"statistics\\": {\\n      \\"total_customers\\": { \\"previous\\": 3, \\"current\\": 0, \\"progress\\": -100 },\\n      \\"total_orders\\": { \\"previous\\": 3, \\"current\\": 22, \\"progress\\": 633.33 },\\n      \\"total_sales\\": {\\n        \\"previous\\": 24247,\\n        \\"current\\": 90401,\\n        \\"formatted_total\\": \\"$90,401.00\\",\\n        \\"progress\\": 272.83\\n      },\\n      \\"avg_sales\\": {\\n        \\"previous\\": 8082.33,\\n        \\"current\\": 4109.14,\\n        \\"formatted_total\\": \\"$4,109.14\\",\\n        \\"progress\\": -49.16\\n      },\\n      \\"total_unpaid_invoices\\": {\\n        \\"total\\": 959719.38,\\n        \\"formatted_total\\": \\"$959,719.38\\"\\n      }\\n    }\\n  }\\n]\\n"},{"id":"rest-today","title":"Today","description":"Today-only sales/orders/customers progress plus the list of orders placed today. Each order\'s `items` field is pre-rendered admin HTML, not structured data.","query":"curl -X GET \\"https://your-domain.com/api/admin/dashboard/stats?type=today&start=2026-05-03&end=2026-06-02\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"type\\": \\"today\\",\\n    \\"dateRange\\": \\"03 May - 02 Jun\\",\\n    \\"statistics\\": {\\n      \\"total_sales\\": { \\"previous\\": 0, \\"current\\": 1000, \\"formatted_total\\": \\"$1,000.00\\", \\"progress\\": 100 },\\n      \\"total_orders\\": { \\"previous\\": 0, \\"current\\": 2, \\"progress\\": 100 },\\n      \\"total_customers\\": { \\"previous\\": 0, \\"current\\": 0, \\"progress\\": 0 },\\n      \\"orders\\": [\\n        {\\n          \\"id\\": 638,\\n          \\"increment_id\\": 638,\\n          \\"status\\": \\"processing\\",\\n          \\"status_label\\": \\"Processing\\",\\n          \\"payment_method\\": \\"Money Transfer\\",\\n          \\"base_grand_total\\": \\"465.0000\\",\\n          \\"formatted_base_grand_total\\": \\"$465.00\\",\\n          \\"channel_name\\": \\"bagisto store\\",\\n          \\"customer_email\\": \\"demo@gmail.com\\",\\n          \\"customer_name\\": \\" \\",\\n          \\"items\\": \\"<div class=\\\\\\"flex flex-wrap gap-1.5\\\\\\">...pre-rendered admin HTML...</div>\\",\\n          \\"billing_address\\": \\"test, India\\",\\n          \\"created_at\\": \\"02 Jun 2026, 12:44:33\\"\\n        }\\n      ]\\n    }\\n  }\\n]\\n"},{"id":"rest-stock-threshold-products","title":"Stock Threshold Products","description":"Up to 5 products at or under their inventory threshold. Here `statistics` is a flat array of product rows, not an object.","query":"curl -X GET \\"https://your-domain.com/api/admin/dashboard/stats?type=stock-threshold-products&start=2026-05-03&end=2026-06-02\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"type\\": \\"stock-threshold-products\\",\\n    \\"dateRange\\": \\"03 May - 02 Jun\\",\\n    \\"statistics\\": [\\n      {\\n        \\"id\\": 95,\\n        \\"sku\\": \\"Puma-White-variant-2-6\\",\\n        \\"name\\": \\"Variant 2 6\\",\\n        \\"price\\": \\"0.0000\\",\\n        \\"formatted_price\\": \\"$0.00\\",\\n        \\"total_qty\\": \\"0\\",\\n        \\"image\\": null\\n      },\\n      {\\n        \\"id\\": 97,\\n        \\"sku\\": \\"Puma-White-variant-4-6\\",\\n        \\"name\\": \\"Variant 4 6\\",\\n        \\"price\\": \\"0.0000\\",\\n        \\"formatted_price\\": \\"$0.00\\",\\n        \\"total_qty\\": \\"0\\",\\n        \\"image\\": null\\n      }\\n    ]\\n  }\\n]\\n"},{"id":"rest-total-sales","title":"Total Sales (chart)","description":"Powers the \\"Store Stats\\" sales chart — order/sales progress plus an `over_time` series with one bucket per day across the range.","query":"curl -X GET \\"https://your-domain.com/api/admin/dashboard/stats?type=total-sales&start=2026-05-03&end=2026-06-02\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"type\\": \\"total-sales\\",\\n    \\"dateRange\\": \\"03 May - 02 Jun\\",\\n    \\"statistics\\": {\\n      \\"total_orders\\": { \\"previous\\": 3, \\"current\\": 22, \\"progress\\": 633.33 },\\n      \\"total_sales\\": { \\"previous\\": 24247, \\"current\\": 90401, \\"formatted_total\\": \\"$90,401.00\\", \\"progress\\": 272.83 },\\n      \\"over_time\\": [\\n        { \\"label\\": \\"11 May\\", \\"total\\": 0, \\"count\\": 0 },\\n        { \\"label\\": \\"12 May\\", \\"total\\": \\"909.0000\\", \\"count\\": 1 },\\n        { \\"label\\": \\"25 May\\", \\"total\\": \\"18094.0000\\", \\"count\\": 3 }\\n      ]\\n    }\\n  }\\n]\\n"},{"id":"rest-total-visitors","title":"Total Visitors (chart)","description":"Powers the \\"Visitors\\" chart — total vs. unique visitor progress plus an `over_time` series (one bucket per day). Requires visitor/analytics data to be populated.","query":"curl -X GET \\"https://your-domain.com/api/admin/dashboard/stats?type=total-visitors&start=2026-05-03&end=2026-06-02\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"type\\": \\"total-visitors\\",\\n    \\"dateRange\\": \\"03 May - 02 Jun\\",\\n    \\"statistics\\": {\\n      \\"total\\": { \\"previous\\": 0, \\"current\\": 0, \\"progress\\": 0 },\\n      \\"unique\\": { \\"previous\\": 0, \\"current\\": 0, \\"progress\\": 0 },\\n      \\"over_time\\": [\\n        { \\"label\\": \\"31 May\\", \\"total\\": 0 },\\n        { \\"label\\": \\"01 Jun\\", \\"total\\": 0 },\\n        { \\"label\\": \\"02 Jun\\", \\"total\\": 0 }\\n      ]\\n    }\\n  }\\n]\\n"},{"id":"rest-top-selling-products","title":"Top Selling Products","description":"Up to 5 best-selling products by revenue. `statistics` is a flat array; each row carries a nested `images` array.","query":"curl -X GET \\"https://your-domain.com/api/admin/dashboard/stats?type=top-selling-products&start=2026-05-03&end=2026-06-02\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"type\\": \\"top-selling-products\\",\\n    \\"dateRange\\": \\"03 May - 02 Jun\\",\\n    \\"statistics\\": [\\n      {\\n        \\"id\\": 2359,\\n        \\"name\\": \\"Horizon Arc 49\\\\\\" OLED Curved Gaming Monitor\\",\\n        \\"price\\": \\"4000.0000\\",\\n        \\"formatted_price\\": \\"$3,899.00\\",\\n        \\"revenue\\": \\"38990.0000\\",\\n        \\"formatted_revenue\\": \\"$38,990.00\\",\\n        \\"images\\": [\\n          {\\n            \\"id\\": 786,\\n            \\"type\\": \\"images\\",\\n            \\"path\\": \\"product/2359/Whw0RJrR1dLPn5HHkyk7G7hiUpY6aH8BFYOE7rlc.webp\\",\\n            \\"product_id\\": 2359,\\n            \\"position\\": 1,\\n            \\"url\\": \\"https://your-domain.com/storage/product/2359/Whw0RJrR1dLPn5HHkyk7G7hiUpY6aH8BFYOE7rlc.webp\\"\\n          }\\n        ]\\n      }\\n    ]\\n  }\\n]\\n"},{"id":"rest-top-customers","title":"Top Customers","description":"Up to 5 customers with the most sales in the range. `statistics` is a flat array. `id` may be null for guest checkouts.","query":"curl -X GET \\"https://your-domain.com/api/admin/dashboard/stats?type=top-customers&start=2026-05-03&end=2026-06-02\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"type\\": \\"top-customers\\",\\n    \\"dateRange\\": \\"03 May - 02 Jun\\",\\n    \\"statistics\\": [\\n      {\\n        \\"id\\": 129,\\n        \\"email\\": \\"demo@gmail.com\\",\\n        \\"full_name\\": \\"webkul bagisto\\",\\n        \\"total\\": \\"35776.0000\\",\\n        \\"orders\\": 6,\\n        \\"formatted_total\\": \\"$35,776.00\\",\\n        \\"datetime\\": null\\n      },\\n      {\\n        \\"id\\": null,\\n        \\"email\\": \\"kesh@king.com\\",\\n        \\"full_name\\": \\"Kesh King\\",\\n        \\"total\\": \\"26504.0000\\",\\n        \\"orders\\": 10,\\n        \\"formatted_total\\": \\"$26,504.00\\",\\n        \\"datetime\\": null\\n      }\\n    ]\\n  }\\n]\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/dashboard/stats.md","filePath":"api/rest-api/admin/dashboard/stats.md","lastUpdated":1783079210000}'),r={name:"api/rest-api/admin/dashboard/stats.md"};function s(n,t,c,i,l,p){return a(),o("div",null,t[0]||(t[0]=[d('<h1 id="dashboard-statistics" tabindex="-1">Dashboard Statistics <a class="header-anchor" href="#dashboard-statistics" aria-label="Permalink to &quot;Dashboard Statistics&quot;">​</a></h1><p>Returns the aggregate statistics that power the Bagisto admin <strong>Dashboard</strong> screen — sales, orders, customers, visitors, stock alerts, top products and top customers.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Endpoint</strong></td><td><code>GET /api/admin/dashboard/stats</code></td></tr><tr><td><strong>Returns</strong></td><td>A JSON <strong>array</strong> with a single element: <code>[ { type, dateRange, statistics } ]</code></td></tr></tbody></table><p>All admin endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p><h2 id="understanding-type-—-the-dashboard-is-seven-separate-calls" tabindex="-1">Understanding <code>type</code> — the dashboard is <strong>seven</strong> separate calls <a class="header-anchor" href="#understanding-type-—-the-dashboard-is-seven-separate-calls" aria-label="Permalink to &quot;Understanding `type` — the dashboard is **seven** separate calls&quot;">​</a></h2><p>This is the most important thing to understand about this API.</p><p>The Bagisto admin Dashboard you see in the panel is <strong>not one response</strong>. The page is assembled from <strong>seven independent requests</strong>, one per section, and each is selected with the <code>?type=</code> query parameter. These seven groups are exactly the sections of the admin Dashboard screen — no more, no less.</p><p>So a single call returns <strong>one section</strong> of the dashboard. To render the full screen, call the endpoint once per <code>type</code> (or only for the sections you need). The <code>statistics</code> payload <strong>changes shape per <code>type</code></strong> — sometimes an object, sometimes a flat array — so always branch on <code>type</code> when consuming it.</p><h3 id="which-type-maps-to-which-part-of-the-dashboard" tabindex="-1">Which <code>type</code> maps to which part of the dashboard <a class="header-anchor" href="#which-type-maps-to-which-part-of-the-dashboard" aria-label="Permalink to &quot;Which `type` maps to which part of the dashboard&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dashboard section (admin panel)</th><th><code>type</code></th><th><code>statistics</code> is</th></tr></thead><tbody><tr><td><strong>Overall Details</strong> cards (Total Sales / Orders / Customers / Average Order Sale / Total Unpaid Invoices)</td><td><code>over-all</code></td><td>object</td></tr><tr><td><strong>Today&#39;s Details</strong> + today&#39;s order list</td><td><code>today</code></td><td>object</td></tr><tr><td><strong>Stock Threshold</strong> product list</td><td><code>stock-threshold-products</code></td><td>array</td></tr><tr><td><strong>Store Stats</strong> sales chart</td><td><code>total-sales</code></td><td>object (with <code>over_time</code> series)</td></tr><tr><td><strong>Visitors</strong> chart</td><td><code>total-visitors</code></td><td>object (with <code>over_time</code> series)</td></tr><tr><td><strong>Top Selling Products</strong> list</td><td><code>top-selling-products</code></td><td>array</td></tr><tr><td><strong>Customer With Most Sales</strong> list</td><td><code>top-customers</code></td><td>array</td></tr></tbody></table><p><code>over-all</code> is the default — if you omit <code>?type=</code>, you get the &quot;Overall Details&quot; cards.</p><h2 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>type</code></td><td>enum</td><td>No</td><td>One of the seven values above. Defaults to <code>over-all</code>. An unknown value returns <strong>400</strong> (<code>invalid-type</code>).</td></tr><tr><td><code>start</code></td><td>date (YYYY-MM-DD)</td><td>No</td><td>Lower bound of the reporting window. Defaults to <strong>30 days ago</strong>.</td></tr><tr><td><code>end</code></td><td>date (YYYY-MM-DD)</td><td>No</td><td>Upper bound. Defaults to <strong>today</strong>.</td></tr><tr><td><code>channel</code></td><td>string</td><td>No</td><td>Channel <strong>code</strong> to scope the figures to a single channel. Defaults to all channels.</td></tr></tbody></table><p><code>start</code> / <code>end</code> drive both the figures and the <code>previous</code> baseline used for each <code>progress</code> percentage — the previous period is the same-length window immediately before <code>start</code>.</p><h2 id="response-envelope" tabindex="-1">Response envelope <a class="header-anchor" href="#response-envelope" aria-label="Permalink to &quot;Response envelope&quot;">​</a></h2><p>The endpoint always returns a <strong>single-element array</strong>: <code>[ { type, dateRange, statistics } ]</code>.</p><ul><li><code>type</code> — echoes back the requested group.</li><li><code>dateRange</code> — a human-readable label for the window (e.g. <code>&quot;03 May - 02 Jun&quot;</code>). <em>(This is fully populated over REST; it is <code>null</code> over the GraphQL transport.)</em></li><li><code>statistics</code> — an object or array whose shape depends on <code>type</code> (documented below).</li></ul><h2 id="response-shapes-by-type" tabindex="-1">Response shapes by <code>type</code> <a class="header-anchor" href="#response-shapes-by-type" aria-label="Permalink to &quot;Response shapes by `type`&quot;">​</a></h2><p>Figures with a <code>previous</code> / <code>current</code> / <code>progress</code> shape are period comparisons: <code>current</code> is the chosen window, <code>previous</code> is the preceding window of equal length, and <code>progress</code> is the percentage change (can be negative).</p><h3 id="over-all" tabindex="-1"><code>over-all</code> <a class="header-anchor" href="#over-all" aria-label="Permalink to &quot;`over-all`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>total_customers</code></td><td><code>{ previous, current, progress }</code></td><td>New customers registered.</td></tr><tr><td><code>total_orders</code></td><td><code>{ previous, current, progress }</code></td><td>Orders placed.</td></tr><tr><td><code>total_sales</code></td><td><code>{ previous, current, formatted_total, progress }</code></td><td>Gross sales; <code>formatted_total</code> is the current value in base currency.</td></tr><tr><td><code>avg_sales</code></td><td><code>{ previous, current, formatted_total, progress }</code></td><td>Average order value.</td></tr><tr><td><code>total_unpaid_invoices</code></td><td><code>{ total, formatted_total }</code></td><td>Outstanding invoice amount (no period comparison).</td></tr></tbody></table><h3 id="today" tabindex="-1"><code>today</code> <a class="header-anchor" href="#today" aria-label="Permalink to &quot;`today`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>total_sales</code></td><td><code>{ previous, current, formatted_total, progress }</code></td><td>Today&#39;s sales vs. yesterday.</td></tr><tr><td><code>total_orders</code></td><td><code>{ previous, current, progress }</code></td><td>Today&#39;s orders.</td></tr><tr><td><code>total_customers</code></td><td><code>{ previous, current, progress }</code></td><td>Today&#39;s new customers.</td></tr><tr><td><code>orders</code></td><td><code>array</code></td><td>Orders placed today. Each row: <code>id</code>, <code>increment_id</code>, <code>status</code>, <code>status_label</code>, <code>payment_method</code>, <code>base_grand_total</code>, <code>formatted_base_grand_total</code>, <code>channel_name</code>, <code>customer_email</code>, <code>customer_name</code>, <code>items</code>, <code>billing_address</code>, <code>created_at</code>.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title"><code>orders[].items</code> is admin HTML</p><p>The <code>items</code> field is a <strong>pre-rendered admin-panel Blade snippet</strong> (an HTML string of product thumbnails), carried over verbatim from core. It is not structured data — a headless client should ignore it and fetch line items from the Orders API (<code>/api/admin/orders/{id}</code>) when product detail is needed.</p></div><h3 id="stock-threshold-products" tabindex="-1"><code>stock-threshold-products</code> <a class="header-anchor" href="#stock-threshold-products" aria-label="Permalink to &quot;`stock-threshold-products`&quot;">​</a></h3><p><code>statistics</code> is an <strong>array</strong> (up to 5 rows). Each row: <code>id</code>, <code>sku</code>, <code>name</code>, <code>price</code>, <code>formatted_price</code>, <code>total_qty</code>, <code>image</code> (base-image URL or <code>null</code>).</p><h3 id="total-sales" tabindex="-1"><code>total-sales</code> <a class="header-anchor" href="#total-sales" aria-label="Permalink to &quot;`total-sales`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>total_orders</code></td><td><code>{ previous, current, progress }</code></td><td>Orders in the window.</td></tr><tr><td><code>total_sales</code></td><td><code>{ previous, current, formatted_total, progress }</code></td><td>Sales in the window.</td></tr><tr><td><code>over_time</code></td><td><code>array</code> of <code>{ label, total, count }</code></td><td>One bucket <strong>per day</strong> across <code>start</code>→<code>end</code> for the chart line. <code>total</code> is sales, <code>count</code> is order count.</td></tr></tbody></table><h3 id="total-visitors" tabindex="-1"><code>total-visitors</code> <a class="header-anchor" href="#total-visitors" aria-label="Permalink to &quot;`total-visitors`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>total</code></td><td><code>{ previous, current, progress }</code></td><td>All visits.</td></tr><tr><td><code>unique</code></td><td><code>{ previous, current, progress }</code></td><td>Unique visitors.</td></tr><tr><td><code>over_time</code></td><td><code>array</code> of <code>{ label, total }</code></td><td>One bucket per day for the chart.</td></tr></tbody></table><p>Visitor figures depend on the Bagisto visitor/analytics tables being populated; on a fresh store they are <code>0</code>.</p><h3 id="top-selling-products" tabindex="-1"><code>top-selling-products</code> <a class="header-anchor" href="#top-selling-products" aria-label="Permalink to &quot;`top-selling-products`&quot;">​</a></h3><p><code>statistics</code> is an <strong>array</strong> (up to 5 rows). Each row: <code>id</code>, <code>name</code>, <code>price</code>, <code>formatted_price</code>, <code>revenue</code>, <code>formatted_revenue</code>, and <code>images</code> (array of <code>{ id, type, path, product_id, position, url }</code>).</p><h3 id="top-customers" tabindex="-1"><code>top-customers</code> <a class="header-anchor" href="#top-customers" aria-label="Permalink to &quot;`top-customers`&quot;">​</a></h3><p><code>statistics</code> is an <strong>array</strong> (up to 5 rows). Each row: <code>id</code> (may be <code>null</code> for guest checkouts), <code>email</code>, <code>full_name</code> (may be <code>null</code>), <code>total</code>, <code>orders</code>, <code>formatted_total</code>, <code>datetime</code>.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>HTTP</th><th>Body</th></tr></thead><tbody><tr><td>Missing / invalid Bearer token</td><td><code>401</code></td><td><code>{ &quot;message&quot;: &quot;Unauthenticated.&quot;, &quot;error&quot;: &quot;unauthenticated&quot; }</code></td></tr><tr><td>Unknown <code>type</code> value</td><td><code>400</code></td><td><code>{ ... &quot;Invalid dashboard stat type.&quot; }</code></td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/api/graphql-api/admin/dashboard/stats.html">Dashboard Statistics (GraphQL)</a> — same data over the <code>statsAdminDashboard</code> query.</li><li><a href="/api/rest-api/admin/reporting/">Reporting</a> — deeper, dedicated sales / customer / product report endpoints.</li></ul>',39)]))}const m=e(r,[["render",s]]);export{u as __pageData,m as default};
